        const double pix = px[i];
        const double piy = py[i];
        const double piz = pz[i];

        for (int j = 0; j < n; j++) {
            double dx = px[j] - pix;
            double dy = py[j] - piy;
            double dz = pz[j] - piz;

            /* Softening factor 1e-9 prevents division by zero. */
            double r2 = dx * dx + dy * dy + dz * dz + 1e-9;

